{
  "items": [
    {
      "name": "LiouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "definition",
      "type": "ℝ → ℝ → Prop"
    },
    {
      "name": "LiouvilleWith.irrational",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p x : ℝ}, LiouvilleWith p x → 1 < p → Irrational x"
    },
    {
      "name": "Liouville",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "definition",
      "type": "ℝ → Prop"
    },
    {
      "name": "ae_not_liouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Measure",
      "kind": "theorem",
      "type": "∀ᵐ (x : ℝ), ∀ p > 2, ¬LiouvilleWith p x"
    },
    {
      "name": "liouvilleWith_one",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ (x : ℝ), LiouvilleWith 1 x"
    },
    {
      "name": "Real.exists_rat_abs_sub_lt_and_lt_of_irrational",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ : ℝ}, Irrational ξ → ∀ (q : ℚ), ∃ q', |ξ - ↑q'| < 1 / ↑q'.den ^ 2 ∧ |ξ - ↑q'| < |ξ - ↑q|"
    },
    {
      "name": "setOf_liouville_eq_irrational_inter_iInter_iUnion",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Residual",
      "kind": "theorem",
      "type": "{x | Liouville x} = {x | Irrational x} ∩ ⋂ n, ⋃ a, ⋃ b, ⋃ (_ : 1 < b), Metric.ball (↑a / ↑b) (1 / ↑b ^ n)"
    },
    {
      "name": "LiouvilleWith.frequently_lt_rpow_neg",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p q x : ℝ}, LiouvilleWith p x → q < p → ∃ᶠ (n : ℕ) in Filter.atTop, ∃ m, x ≠ ↑m / ↑n ∧ |x - ↑m / ↑n| < ↑n ^ (-q)"
    },
    {
      "name": "Real.infinite_rat_abs_sub_lt_one_div_den_sq_of_irrational",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ : ℝ}, Irrational ξ → {q | |ξ - ↑q| < 1 / ↑q.den ^ 2}.Infinite"
    },
    {
      "name": "setOf_liouvilleWith_subset_aux",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Measure",
      "kind": "theorem",
      "type": "{x | ∃ p > 2, LiouvilleWith p x} ⊆\n  ⋃ m,\n    (fun x => x + ↑m) ⁻¹'\n      ⋃ n, ⋃ (_ : n > 0), {x | ∃ᶠ (b : ℕ) in Filter.atTop, ∃ a ∈ Finset.Icc 0 ↑b, |x - ↑a / ↑b| < 1 / ↑b ^ (2 + 1 / ↑n)}"
    },
    {
      "name": "Liouville.irrational",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, Liouville x → Irrational x"
    },
    {
      "name": "volume_iUnion_setOf_liouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Measure",
      "kind": "theorem",
      "type": "MeasureTheory.volume (⋃ p, ⋃ (_ : 2 < p), {x | LiouvilleWith p x}) = 0"
    }
  ]
}
